css:
.mgn-sim-container {
    padding: 28px;
    background: linear-gradient(180deg, #0d1b2a 0%, #1b263b 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #e8e9ed;
}

.mgn-sim-container h1, .mgn-sim-container h3 {
    color: #f4e4bc;
    margin: 0;
}

.mgn-sim-header {
    background: rgba(13, 27, 42, 0.6);
    border-left: 4px solid #d4af37;
    padding: 24px 32px;
    margin-bottom: 24px;
    border-radius: 4px;
    box-shadow: 0 4px 18px rgba(0,0,0,0.3);
}
.mgn-sim-header h1 {
    font-size: 1.6rem;
    letter-spacing: 0.04em;
    margin-bottom: 6px;
}
.mgn-sim-header .mgn-sim-sub {
    color: #a9b3c1;
    font-size: 0.95rem;
    margin: 8px 0 0 0;
    letter-spacing: 0.02em;
}
.mgn-sim-badge {
    display: inline-block;
    background: rgba(212, 175, 55, 0.15);
    border: 1px solid rgba(212, 175, 55, 0.5);
    color: #d4af37;
    padding: 4px 12px;
    border-radius: 12px;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    font-weight: 600;
    margin-bottom: 14px;
}

.mgn-sim-period-bar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    background: #1b263b;
    border: 1px solid #2d3f55;
    border-radius: 6px;
    padding: 14px 24px;
    margin-bottom: 24px;
}
.mgn-sim-round-tag {
    color: #a9b3c1;
    font-size: 0.85rem;
    letter-spacing: 0.04em;
}
.mgn-sim-round-tag span {
    color: #f4e4bc;
    font-weight: 600;
    margin: 0 4px;
}
.mgn-sim-round-name {
    color: #d4af37;
    font-size: 1.05rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.16em;
}

.mgn-sim-briefing {
    background: rgba(244, 228, 188, 0.06);
    border: 1px solid rgba(244, 228, 188, 0.18);
    border-radius: 8px;
    padding: 22px 26px;
    margin-bottom: 24px;
}
.mgn-sim-briefing h3 {
    color: #f4e4bc;
    font-size: 1.05rem;
    margin-bottom: 10px;
    letter-spacing: 0.02em;
}
.mgn-sim-briefing p {
    color: #cfd5de;
    font-size: 0.95rem;
    line-height: 1.55;
    margin: 0;
}

.mgn-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
    gap: 14px;
    margin-bottom: 26px;
}
.mgn-sim-kpi-card {
    background: #1b263b;
    border: 1px solid #2d3f55;
    border-radius: 8px;
    padding: 18px 18px;
    position: relative;
    overflow: hidden;
    transition: transform 0.18s ease, box-shadow 0.18s ease;
}
.mgn-sim-kpi-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 2px;
    background: linear-gradient(90deg, #d4af37, #f4e4bc);
}
.mgn-sim-kpi-card:hover {
    transform: translateY(-2px);
    box-shadow: 0 8px 22px rgba(0,0,0,0.35);
}
.mgn-sim-kpi-label {
    color: #a9b3c1;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    margin-bottom: 8px;
    font-weight: 600;
}
.mgn-sim-kpi-value {
    font-size: 1.7rem;
    font-weight: 700;
    color: #f4e4bc;
    letter-spacing: -0.01em;
}

.mgn-sim-controls {
    background: #1b263b;
    border: 1px solid #2d3f55;
    border-radius: 8px;
    padding: 26px 28px;
    margin-bottom: 26px;
}
.mgn-sim-controls h3 {
    color: #f4e4bc;
    font-size: 1.05rem;
    margin-bottom: 18px;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    border-bottom: 1px solid #2d3f55;
    padding-bottom: 10px;
}

.mgn-sim-field {
    margin-bottom: 18px;
}
.mgn-sim-field label {
    display: block;
    color: #cfd5de;
    font-size: 0.85rem;
    margin-bottom: 8px;
    font-weight: 500;
    line-height: 1.4;
}

.mgn-sim-controls select,
.mgn-sim-controls input[type='number'],
.mgn-sim-controls input[type='text'] {
    background: #0d1b2a;
    border: 1px solid #2d3f55;
    color: #e8e9ed;
    border-radius: 4px;
    padding: 9px 12px;
    width: 100%;
    font-size: 0.9rem;
    transition: border-color 0.18s ease;
}
.mgn-sim-controls select:focus,
.mgn-sim-controls input[type='number']:focus,
.mgn-sim-controls input[type='text']:focus {
    outline: none;
    border-color: #d4af37;
    box-shadow: 0 0 0 2px rgba(212, 175, 55, 0.25);
}
.mgn-sim-controls select option {
    background: #1b263b;
    color: #e8e9ed;
}

.mgn-sim-controls .btn {
    margin-top: 10px;
    margin-right: 10px;
    border-radius: 4px;
    padding: 10px 22px;
    font-weight: 600;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    font-size: 0.82rem;
    transition: all 0.18s ease;
}
.mgn-sim-controls #nextPeriodBtn {
    background: #d4af37;
    border: 1px solid #d4af37;
    color: #0d1b2a;
}
.mgn-sim-controls #nextPeriodBtn:hover {
    background: #f4e4bc;
    border-color: #f4e4bc;
}
.mgn-sim-controls #undoBtn {
    background: transparent;
    border: 1px solid #2d3f55;
    color: #a9b3c1;
}
.mgn-sim-controls #undoBtn:hover {
    border-color: #a9b3c1;
    color: #e8e9ed;
}

.mgn-sim-history {
    background: #1b263b;
    border: 1px solid #2d3f55;
    border-radius: 8px;
    padding: 22px 26px;
    margin-bottom: 26px;
}
.mgn-sim-history h3 {
    color: #f4e4bc;
    font-size: 1.05rem;
    margin-bottom: 14px;
    text-transform: uppercase;
    letter-spacing: 0.1em;
}
.mgn-sim-history table {
    color: #cfd5de;
    font-size: 0.88rem;
    margin: 0;
}
.mgn-sim-history table thead th {
    color: #d4af37;
    border-bottom: 1px solid #2d3f55;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    font-size: 0.72rem;
    font-weight: 600;
}
.mgn-sim-history table tbody td {
    border-top: 1px solid #2d3f55;
    padding: 10px 8px;
}
.mgn-sim-history table tbody tr:hover {
    background: rgba(212, 175, 55, 0.04);
}

.mgn-sim-charts {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px;
    margin-bottom: 16px;
}
.mgn-sim-chart-wrap {
    background: #1b263b;
    border: 1px solid #2d3f55;
    border-radius: 8px;
    padding: 18px;
    height: 320px;
}

@media (max-width: 768px) {
    .mgn-sim-container { padding: 14px; }
    .mgn-sim-header { padding: 18px 20px; }
    .mgn-sim-header h1 { font-size: 1.25rem; }
    .mgn-sim-period-bar { flex-direction: column; align-items: flex-start; gap: 8px; }
    .mgn-sim-charts { grid-template-columns: 1fr; }
    .mgn-sim-kpi-value { font-size: 1.4rem; }
    .mgn-sim-controls, .mgn-sim-history, .mgn-sim-briefing { padding: 16px 18px; }
}


/* v1.1.0 additions: accessible focus ring + completion summary */
.mgn-sim-container :is(select, input, button):focus-visible { outline: 3px solid #d4af37; outline-offset: 2px; }
.mgn-completion { color: #f4e4bc; padding: 8px 4px; text-align: center; }
.mgn-completion-title { color: #d4af37; margin: 0 0 12px; font-size: 1.4rem; }
.mgn-completion-score { margin: 6px 0 16px; }
.mgn-completion-score .acs-num { font-size: 2.6rem; font-weight: 700; color: #5fb3a1; }
.mgn-completion-score .acs-max { font-size: 1.1rem; color: #cfd5de; margin-left: 2px; }
.mgn-completion-score .acs-cap { font-size: .72rem; text-transform: uppercase; letter-spacing: .06em; color: #cfd5de; margin-top: 2px; }
.mgn-completion-kpis { display: flex; gap: 14px; justify-content: center; margin: 12px 0 16px; flex-wrap: wrap; }
.mgn-completion-kpis .ack { background: rgba(255,255,255,0.05); border: 1px solid rgba(212,175,55,0.35); border-radius: 10px; padding: 10px 16px; min-width: 112px; }
.mgn-completion-kpis .ack-label { font-size: .68rem; text-transform: uppercase; letter-spacing: .05em; color: #cfd5de; margin-bottom: 4px; }
.mgn-completion-kpis .ack-value { font-size: 1.25rem; font-weight: 600; color: #f4e4bc; }
.mgn-completion-rating { color: #cfd5de; margin: 10px auto; max-width: 580px; line-height: 1.5; }
.mgn-completion-takeaways { text-align: left; max-width: 660px; margin: 14px auto 0; }
.mgn-completion-takeaways h4 { color: #d4af37; font-size: .95rem; margin: 0 0 8px; }
.mgn-completion-takeaways ul { margin: 0; padding-left: 20px; }
.mgn-completion-takeaways li { margin-bottom: 6px; color: #dfe4ea; line-height: 1.45; }
.mgn-completion-thanks { color: #cfd5de; font-size: .85rem; margin-top: 16px; }

