(function() {
    'use strict';

    class NegotiationAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Mutual-Gains Negotiation';
            this.version = '1.1.0';
            this.ROUNDS = [
                { name: 'Diagnose', titleKey: 'brief_diag_title', bodyKey: 'brief_diag_body' },
                { name: 'Design',   titleKey: 'brief_design_title', bodyKey: 'brief_design_body' },
                { name: 'Defend',   titleKey: 'brief_defend_title', bodyKey: 'brief_defend_body' }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    valueCapture: 0,
                    defensibility: 50,
                    relationship: 60,
                    anchorDiscipline: 50,
                    croConfidence: 40,
                    jointPie: 36.3,
                    captureHistory: [],
                    defensibilityHistory: [],
                    relationshipHistory: [],
                    anchorHistory: [],
                    croHistory: [],
                    jointPieHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    framing: 'mixed',
                    batnaRead: 3,
                    memoApproach: 'stress',
                    peopleProblem: 3,
                    packageChoice: 'B',
                    openingAnchor: 6.4,
                    framingMode: 'package',
                    disclosure: 'conditional',
                    fallback: 'yes',
                    croAnswer: 'both',
                    gcCovered: 'yes',
                    cfoCovered: 'yes'
                };
            }
            var self = this;
            setTimeout(function() { self._updateBriefing(state); }, 100);
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var t = window.mySimulation && window.mySimulation.t ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };

            var rn = document.getElementById('roundName');
            if (rn) rn.textContent = round.name;
            var bt = document.getElementById('briefingTitle');
            if (bt) bt.textContent = t(round.titleKey);
            var bx = document.getElementById('briefingText');
            if (bx) bx.textContent = t(round.bodyKey);

            var r1 = document.getElementById('round1Controls');
            var r2 = document.getElementById('round2Controls');
            var r3 = document.getElementById('round3Controls');
            if (r1) r1.style.display = idx === 0 ? 'block' : 'none';
            if (r2) r2.style.display = idx === 1 ? 'block' : 'none';
            if (r3) r3.style.display = idx === 2 ? 'block' : 'none';
        }

        validateDecisions(decisions) {
            var state = window.mySimulation.state;
            this._updateBriefing(state);
            var idx = (state.currentPeriod || 1) - 1;

            if (idx === 0) {
                var f = document.getElementById('framingInput');
                if (f) decisions.framing = f.value;
                var b = document.getElementById('batnaInput');
                if (b) decisions.batnaRead = parseInt(b.value);
                var m = document.getElementById('memoInput');
                if (m) decisions.memoApproach = m.value;
                var p = document.getElementById('peopleInput');
                if (p) decisions.peopleProblem = parseInt(p.value);
            } else if (idx === 1) {
                var pk = document.getElementById('packageInput');
                if (pk) decisions.packageChoice = pk.value;
                var oa = document.getElementById('anchorInput');
                if (oa) decisions.openingAnchor = parseFloat(oa.value);
                if (!decisions.openingAnchor || decisions.openingAnchor < 5.0 || decisions.openingAnchor > 8.5) {
                    window.mySimulation.uiManager.showNotification(
                        window.mySimulation.t('anchor_warning'), 'warning'
                    );
                    return false;
                }
                var fm = document.getElementById('framingModeInput');
                if (fm) decisions.framingMode = fm.value;
                var dc = document.getElementById('disclosureInput');
                if (dc) decisions.disclosure = dc.value;
                var fb = document.getElementById('fallbackInput');
                if (fb) decisions.fallback = fb.value;
            } else {
                var ca = document.getElementById('croAnswerInput');
                if (ca) decisions.croAnswer = ca.value;
                var gc = document.getElementById('gcInput');
                if (gc) decisions.gcCovered = gc.value;
                var cf = document.getElementById('cfoInput');
                if (cf) decisions.cfoCovered = cf.value;
            }
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var idx = (state.currentPeriod || 1) - 1;
            var ds = state.domainState;
            var dCapture = 0, dDef = 0, dRel = 0, dAnchor = 0, dCro = 0, dPie = 0;

            if (idx === 0) {
                if (d.framing === 'interest')      { dDef += 18; dPie += 4; dCapture += 6; }
                else if (d.framing === 'mixed')    { dDef += 8;  dPie += 1; dCapture += 2; }
                else                                { dDef -= 6;  dRel -= 5; dPie -= 2; }

                if (d.batnaRead >= 4)              { dDef += 10; dCapture += 4; }
                else if (d.batnaRead === 3)        { dDef += 3; }
                else                                { dDef -= 8; dCapture -= 4; }

                if (d.memoApproach === 'stress')   { dDef += 12; dCro += 8; }
                else if (d.memoApproach === 'use') { dDef += 4;  dCro -= 12; dRel -= 10; }
                else                                { dDef -= 4; }

                if (d.peopleProblem >= 4)          { dRel += 12; dCro += 4; }
                else if (d.peopleProblem === 3)    { dRel += 4; }
                else                                { dRel -= 8; dCro -= 4; }

            } else if (idx === 1) {
                if (d.packageChoice === 'C')       { dCapture += 16; dPie += 12; dCro += 14; }
                else if (d.packageChoice === 'B')  { dCapture += 4;  dPie += 3;  dCro -= 5; }
                else                                { dCapture -= 8; dPie -= 4;  dCro -= 12; }

                if (d.openingAnchor >= 7.0)        { dAnchor += 18; dCapture += 6; }
                else if (d.openingAnchor >= 6.6)   { dAnchor += 6;  dCapture += 2; }
                else                                { dAnchor -= 14; dCapture -= 6; }

                if (d.framingMode === 'package')   { dDef += 14; dCapture += 6; }
                else                                { dDef -= 10; dCapture -= 8; }

                if (d.disclosure === 'conditional'){ dDef += 10; dRel += 6; }
                else if (d.disclosure === 'full')  { dDef -= 8;  dCapture -= 6; }
                else                                { dDef -= 4;  dRel -= 8; }

                if (d.fallback === 'yes')          { dDef += 8;  dCro += 10; }
                else                                { dCro -= 12; }

            } else {
                if (d.croAnswer === 'both')        { dCro += 16; dDef += 4; }
                else if (d.croAnswer === 'revenue'){ dCro += 4; }
                else                                { dCro -= 4; }

                if (d.gcCovered === 'yes')         { dDef += 12; dRel += 4; }
                else                                { dDef -= 14; dCro -= 8; dRel -= 6; }

                if (d.cfoCovered === 'yes')        { dCro += 10; dDef += 4; }
                else                                { dCro -= 6; }
            }

            ds.valueCapture     = Math.max(0,  Math.min(100, ds.valueCapture     + dCapture));
            ds.defensibility    = Math.max(0,  Math.min(100, ds.defensibility    + dDef));
            ds.relationship     = Math.max(0,  Math.min(100, ds.relationship     + dRel));
            ds.anchorDiscipline = Math.max(0,  Math.min(100, ds.anchorDiscipline + dAnchor));
            ds.croConfidence    = Math.max(0,  Math.min(100, ds.croConfidence    + dCro));
            ds.jointPie         = Math.max(20, ds.jointPie + dPie);

            ds.captureHistory.push(ds.valueCapture);
            ds.defensibilityHistory.push(ds.defensibility);
            ds.relationshipHistory.push(ds.relationship);
            ds.anchorHistory.push(ds.anchorDiscipline);
            ds.croHistory.push(ds.croConfidence);
            ds.jointPieHistory.push(parseFloat(ds.jointPie.toFixed(1)));

            // v1.1.0 FIX: persist a normalized 0-100 score so the instructor results panel
            // (results_utils.php express_resolveDomainScore -> domainState.performance.
            // overallScore) shows a real score instead of "-". Additive; round logic unchanged.
            ds.performance = {
                overallScore: this._computeScore(ds),
                composite: Math.round((ds.defensibility + ds.relationship + ds.croConfidence + ds.anchorDiscipline) / 4),
                jointPie: parseFloat(ds.jointPie.toFixed(1))
            };

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                round: this.ROUNDS[idx].name,
                valueCapture: ds.valueCapture,
                defensibility: ds.defensibility,
                relationship: ds.relationship,
                anchorDiscipline: ds.anchorDiscipline,
                croConfidence: ds.croConfidence,
                jointPie: ds.jointPie
            };
        }

        _computeScore(ds) {
            // Composite 0-100: the four-metric negotiation composite (defensibility,
            // relationship, CRO confidence, anchor discipline) 60, value capture 20,
            // joint-pie expansion from 36.3 baseline toward the 52M target 20.
            var composite = ((ds.defensibility || 0) + (ds.relationship || 0) + (ds.croConfidence || 0) + (ds.anchorDiscipline || 0)) / 4;
            var capture = Math.max(0, Math.min(100, ds.valueCapture || 0));
            var pieNorm = Math.max(0, Math.min(1, ((ds.jointPie || 36) - 36) / 16));
            var raw = (composite * 0.6) + (capture * 0.2) + (pieNorm * 100 * 0.2);
            return Math.round(Math.max(0, Math.min(100, raw)));
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('valueCaptureDisplay',   'domainState.valueCapture',     function(v) { return Math.round(v) + '%'; });
            uiManager.bind('defensibilityDisplay',  'domainState.defensibility',    function(v) { return Math.round(v) + '/100'; });
            uiManager.bind('relationshipDisplay',   'domainState.relationship',     function(v) { return Math.round(v) + '/100'; });
            uiManager.bind('anchorDisplay',         'domainState.anchorDiscipline', function(v) { return Math.round(v) + '/100'; });
            uiManager.bind('croDisplay',            'domainState.croConfidence',    function(v) { return Math.round(v) + '/100'; });
            uiManager.bind('jointPieDisplay',       'domainState.jointPie',         function(v) { return '$' + v.toFixed(1) + 'M'; });
        }

        getChartConfig() {
            var commonScales = {
                y: { beginAtZero: true, max: 100, ticks: { color: '#cfd5de' }, grid: { color: 'rgba(255,255,255,0.06)' } },
                x: { ticks: { color: '#cfd5de' }, grid: { color: 'rgba(255,255,255,0.06)' } }
            };
            return {
                metricsChart: {
                    type: 'line',
                    data: {
                        labels: [],
                        datasets: [
                            { label: 'Defensibility',     data: [], borderColor: '#d4af37', backgroundColor: 'rgba(212,175,55,0.1)',  borderWidth: 2, tension: 0.25, fill: false },
                            { label: 'Relationship',      data: [], borderColor: '#5fb3a1', backgroundColor: 'rgba(95,179,161,0.1)', borderWidth: 2, tension: 0.25, fill: false },
                            { label: 'CRO Confidence',    data: [], borderColor: '#e07a5f', backgroundColor: 'rgba(224,122,95,0.1)', borderWidth: 2, tension: 0.25, fill: false },
                            { label: 'Anchor Discipline', data: [], borderColor: '#82a7d0', backgroundColor: 'rgba(130,167,208,0.1)',borderWidth: 2, tension: 0.25, fill: false }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Negotiation Metrics by Round', color: '#f4e4bc', font: { size: 13, weight: '600' } },
                            legend: { labels: { color: '#cfd5de', font: { size: 11 } } }
                        },
                        scales: commonScales
                    }
                },
                pieChart: {
                    type: 'bar',
                    data: {
                        labels: [],
                        datasets: [{
                            label: 'Joint Pie ($M)',
                            data: [],
                            backgroundColor: 'rgba(212,175,55,0.7)',
                            borderColor: '#d4af37',
                            borderWidth: 1
                        }]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            title: { display: true, text: 'Joint Value Pool ($M, Cumulative)', color: '#f4e4bc', font: { size: 13, weight: '600' } },
                            legend: { labels: { color: '#cfd5de', font: { size: 11 } } }
                        },
                        scales: {
                            y: { beginAtZero: false, ticks: { color: '#cfd5de' }, grid: { color: 'rgba(255,255,255,0.06)' } },
                            x: { ticks: { color: '#cfd5de' }, grid: { color: 'rgba(255,255,255,0.06)' } }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            var labels = state.domainState.defensibilityHistory.map(function(_, i) { return 'R' + (i + 1); });
            return {
                metricsChart: {
                    labels: labels,
                    datasets: [
                        { data: state.domainState.defensibilityHistory },
                        { data: state.domainState.relationshipHistory },
                        { data: state.domainState.croHistory },
                        { data: state.domainState.anchorHistory }
                    ]
                },
                pieChart: {
                    labels: labels,
                    datasets: [{ data: state.domainState.jointPieHistory }]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            var ds = window.mySimulation.state.domainState;
            var composite = (ds.defensibility + ds.relationship + ds.croConfidence + ds.anchorDiscipline) / 4;

            var t = (window.mySimulation && window.mySimulation.t)
                ? function(k) { return window.mySimulation.t(k); } : function(k) { return k; };

            var perf = t('rating_beginner');
            if (composite > 72 && ds.jointPie > 48) perf = t('rating_excellent');
            else if (composite > 58 && ds.jointPie > 40) perf = t('rating_good');

            var insights = [];
            if (ds.jointPie > 48) insights.push(t('insight_pie_high'));
            else if (ds.jointPie > 40) insights.push(t('insight_pie_mid'));
            else insights.push(t('insight_pie_low'));

            if (ds.croConfidence > 70) insights.push(t('insight_cro_high'));
            else insights.push(t('insight_cro_low'));

            if (ds.relationship > 70) insights.push(t('insight_rel_high'));
            else if (ds.relationship < 50) insights.push(t('insight_rel_low'));

            if (ds.defensibility < 55) insights.push(t('insight_def_low'));
            if (ds.anchorDiscipline < 55) insights.push(t('insight_anchor_low'));

            return {
                overallScore: this._computeScore(ds),
                composite: Math.round(composite),
                jointPie: parseFloat(ds.jointPie.toFixed(1)),
                valueCapture: Math.round(ds.valueCapture),
                performance: perf,
                insights: insights
            };
        }

